// One- and two-bone IK regression (plugin 1.13.0): the poses every pre-1.13 IK scenario of the core
// tests produces, as exact bit patterns. `--ik-golden` prints them; ik-golden.json (generated by the
// 1.12.0 build, before chains and stretch existed) is what the 1.13 solver must still produce bit
// for bit. Included by core-tests.cpp after armRig / ikParityRig / hangingArm / meshParityRig.
// The generated data lives in ik-golden-data.hpp (GOLDEN_1_12).
#pragma once
#include <cstdio>
#include <cstring>
#include "ik-golden-data.hpp"

namespace ikgolden {
using cutout::Json;

std::string hex(double v) {
  uint64_t bits = 0;
  std::memcpy(&bits, &v, sizeof bits);
  char text[24];
  std::snprintf(text, sizeof text, "%016llx", static_cast<unsigned long long>(bits));
  return text;
}
/** World matrices and applied rotations of every bone, bit patterns. */
Json poseBits(const cutout::Pose& p) {
  Json bones = Json::array();
  for (size_t i = 0; i < p.world.size(); i++) {
    const auto& w = p.world[i];
    bones.push_back({hex(w.a), hex(w.b), hex(w.c), hex(w.d), hex(w.e), hex(w.f), hex(p.local(i).rotation), hex(p.local(i).scaleX)});
  }
  return bones;
}
/** Named rigs: every IK shape the 1.3 .. 1.12 tests use (aim, aim axis, two-bone with and without
 *  tip / length tip, mirrored and scaled parents, unreachable, folded, mix, keyed mix/bend). */
std::vector<std::pair<std::string, Json>> rigs() {
  std::vector<std::pair<std::string, Json>> out;
  out.push_back({"arm", armRig(60, 40)});
  Json flip = armRig(60, 40); flip["ik"][0]["bendPositive"] = false; out.push_back({"flip", flip});
  out.push_back({"far", armRig(0, 300)});
  Json shortArm = armRig(10, 0); shortArm["bones"][3]["x"] = 30; out.push_back({"fold", shortArm});
  out.push_back({"zero", armRig(0, 0)});
  Json half = armRig(60, 40); half["ik"][0]["mix"] = 0.5; out.push_back({"half", half});
  Json noTip = armRig(0, 80); noTip["bones"].erase(3); noTip["slots"].erase(1); noTip["attachments"].erase(1); out.push_back({"noTip", noTip});
  int n = 0;
  for (const Json& rootT : {Json{{"rotation", 30}, {"scaleX", 2}, {"scaleY", 0.5}}, Json{{"rotation", -70}, {"scaleX", -1.5}, {"scaleY", 1}}}) {
    Json d = armRig(60, 40);
    for (auto it = rootT.begin(); it != rootT.end(); ++it) d["bones"][0][it.key()] = it.value();
    d["bones"][0]["x"] = 10; d["bones"][0]["y"] = 20;
    out.push_back({"root" + std::to_string(n++), d});
  }
  for (const Json& upperT : {Json{{"scaleX", 1.5}, {"scaleY", 1.5}}, Json{{"scaleX", -1.2}, {"scaleY", -1.2}}, Json{{"scaleX", -1}, {"scaleY", 1}, {"rotation", 40}}, Json{{"scaleX", 2}, {"scaleY", 0.7}}}) {
    Json d = armRig(60, 50);
    for (auto it = upperT.begin(); it != upperT.end(); ++it) d["bones"][1][it.key()] = it.value();
    d["bones"][2]["scaleX"] = 0.8;
    out.push_back({"upper" + std::to_string(n++), d});
  }
  Json mirrored = armRig(60, 40); mirrored["bones"][0]["scaleX"] = -1; mirrored["bones"][4]["x"] = -60; out.push_back({"mirrored", mirrored});
  Json aim = armRig(0, 80); aim["ik"][0]["bones"] = {"upper"}; out.push_back({"aim", aim});
  Json skewAim = aim; skewAim["bones"][0]["rotation"] = 30; skewAim["bones"][0]["scaleX"] = 2; skewAim["bones"][0]["scaleY"] = 0.5; skewAim["bones"][1]["scaleX"] = -1;
  out.push_back({"skewAim", skewAim});
  skewAim["ik"][0]["mix"] = 0.25; out.push_back({"skewAimMix", skewAim});
  Json hang = hangingArm(); hang["ik"] = Json::array({{{"id", "aim"}, {"bones", {"arm"}}, {"target", "t"}, {"aimAxis", 90}}}); out.push_back({"hang", hang});
  hang["bones"][0]["rotation"] = 25; hang["bones"][0]["scaleX"] = 1.5; hang["bones"][0]["scaleY"] = 0.6;
  hang["bones"][1]["scaleX"] = -0.8; hang["bones"][1]["scaleY"] = 1.7; hang["ik"][0]["aimAxis"] = -130;
  out.push_back({"hangOblique", hang});
  // Lower bone with a length (plugin 1.5.0): its own tip is the effector.
  Json lengthTip = armRig(70, 30); lengthTip["bones"][2]["length"] = 45; lengthTip["bones"].erase(3); lengthTip["slots"].erase(1); lengthTip["attachments"].erase(1);
  out.push_back({"lengthTip", lengthTip});
  out.push_back({"parity", ikParityRig()});
  out.push_back({"mesh", meshParityRig()});
  return out;
}
Json dump() {
  Json out = Json::object();
  for (const auto& [name, data] : rigs()) {
    const cutout::Rig r = cutout::parseRig(name, data);
    Json poses = Json::array();
    if (r.clips.empty()) poses.push_back(poseBits(cutout::samplePose(r, -1, 0)));
    for (size_t c = 0; c < r.clips.size(); c++)
      for (double t : {0.0, 120.0, 250.0, 333.5, 500.0, 650.0, 777.25, 999.0}) poses.push_back(poseBits(cutout::samplePose(r, int(c), t)));
    out[name] = poses;
  }
  // A playing instance (irregular updates): the runtime path, not only samplePose.
  cutout::Instance inst(std::make_shared<const cutout::Rig>(cutout::parseRig("parity", ikParityRig())));
  inst.play(0, "reach");
  Json frames = Json::array();
  for (double dt : {16.0, 125.5, 233.25, 180.0, 60.0, 90.0, 210.0, 333.0}) { inst.update(dt); frames.push_back(poseBits(inst.pose())); }
  out["instance"] = frames;
  return out;
}
/** Every scenario still produces the 1.12 bits (world matrices, applied rotations and scales). */
void run() {
  test("ik golden: one/two-bone poses bit for bit as in 1.12", [] {
    const Json want = Json::parse(GOLDEN_1_12), got = dump();
    size_t poses = 0, differ = 0;
    for (auto it = want.begin(); it != want.end(); ++it) {
      check(got.contains(it.key()) && got.at(it.key()).size() == it.value().size(), "scenario " + it.key());
      if (!got.contains(it.key())) continue;
      for (size_t i = 0; i < it.value().size() && i < got.at(it.key()).size(); i++, poses++)
        if (got.at(it.key())[i] != it.value()[i]) { differ++; if (differ < 4) check(false, "differs: " + it.key() + " #" + std::to_string(i)); }
    }
    check(differ == 0 && poses >= 44, "poses compared: " + std::to_string(poses) + ", differing: " + std::to_string(differ));
  });
}
}  // namespace ikgolden
